    function __ESBMC_assume(bool) internal pure {}

    function run(address logAddr) public {
        bool firstReverted;
        c.SetLogFile(logAddr); bool __rev0 = __ESBMC_reverted(); if (__rev0) { firstReverted = true; } else { firstReverted = false; }
        c.Initialized(); if (__ESBMC_reverted()) return;
        bool secondReverted;
        c.SetLogFile(address(0xdead)); bool __rev1 = __ESBMC_reverted(); if (__rev1) { secondReverted = true; } else { secondReverted = false; }
        assert(!firstReverted && secondReverted);
    }

